function playChime() { try { const Ctx = window.AudioContext || window.webkitAudioContext; const ctx = new Ctx(); ctx.resume(); [523.25, 659.25].forEach((freq, i) => { const osc = ctx.createOscillator(); const gain = ctx.createGain(); osc.type = "sine"; osc.frequency.value = freq; const start = ctx.currentTime + i * 0.14; gain.gain.setValueAtTime(0.0001, start); gain.gain.exponentialRampToValueAtTime(0.07, start + 0.04); gain.gain.exponentialRampToValueAtTime(0.0001, start + 0.55); osc.connect(gain); gain.connect(ctx.destination); osc.start(start); osc.stop(start + 0.6); }); } catch { /* audio tidak tersedia */ } }

function downloadAuraCard(aura, alias) { try { const canvas = document.createElement("canvas"); canvas.width = 1080; canvas.height = 1350; const ctx = canvas.getContext("2d"); ctx.fillStyle = "#f7f5f0"; ctx.fillRect(0, 0, 1080, 1350); const cx = 540; const cy = 540; aura.colors.forEach((color, i) => { const angle = (i / aura.colors.length) * Math.PI * 2 - Math.PI / 2; const gx = cx + Math.cos(angle) * 150; const gy = cy + Math.sin(angle) * 150; const grad = ctx.createRadialGradient(gx, gy, 30, gx, gy, 360); grad.addColorStop(0, color); grad.addColorStop(1, "rgba(247,245,240,0)"); ctx.fillStyle = grad; ctx.beginPath(); ctx.arc(cx, cy, 400, 0, Math.PI * 2); ctx.fill(); }); ctx.textAlign = "center"; ctx.fillStyle = "#a5afa7"; ctx.font = "600 24px Arial"; ctx.fillText("A U R A   S A A T   I N I", cx, 190); ctx.fillStyle = "#c98a66"; ctx.font = "italic 400 34px Georgia, serif"; ctx.fillText(`milik ${alias}`, cx, 1000); ctx.fillStyle = "#2b3a33"; ctx.font = "500 80px 'Playfair Display', Georgia, serif"; ctx.fillText(aura.name, cx, 1090); ctx.fillStyle = "#5d6b63"; ctx.font = "400 26px Arial"; const words = aura.description.split(" "); let line = ""; let ly = 1160; words.forEach((word) => { const test = line ? `${line} ${word}` : word; if (ctx.measureText(test).width > 760) { ctx.fillText(line, cx, ly); line = word; ly += 38; } else { line = test; } }); if (line) ctx.fillText(line, cx, ly); ctx.fillStyle = "#a5afa7"; ctx.font = "400 22px Arial"; ctx.fillText("titikjiwa — ruang pulih · " + new Date().toLocaleDateString("id-ID", { day: "numeric", month: "long", year: "numeric" }), cx, 1270); canvas.toBlob((blob) => { const url = URL.createObjectURL(blob); const link = document.createElement("a"); link.href = url; link.download = `aura-titikjiwa-${aura.week_key || "minggu-ini"}.png`; link.click(); URL.revokeObjectURL(url); toast.success("Kartu auramu terunduh."); }); } catch { toast.error("Kartu belum bisa dibuat di peramban ini."); } }

const AuthContext = createContext(null);
function AuthProvider({ children }) {
  const [state, setState] = useState({ loading: true, user: null });
  useEffect(() => { api.get("/auth/me").then(({ data }) => setState({ loading: false, user: data })).catch(() => setState({ loading: false, user: null })); }, []);
  const auth = useMemo(() => ({ ...state, login: async (payload) => { const { data } = await api.post("/auth/login", payload); setState({ loading: false, user: data.user }); return data.user; }, register: async (payload) => { const { data } = await api.post("/auth/register", payload); setState({ loading: false, user: data.user }); return data.user; }, logout: async () => { await api.post("/auth/logout").catch(() => {}); setState({ loading: false, user: null }); } }), [state]);
  return <AuthContext.Provider value={auth}>{children}</AuthContext.Provider>;
}
const useAuth = () => useContext(AuthContext);

